import { getRuntimeConfig } from "@/lib/runtime-config";
import { authHeaders as clerkAuthHeaders } from "@/lib/auth-adapter";
import type { AgentNamespace } from "@/lib/free-storage/types";

async function authHeaders(): Promise<Record<string, string>> {
  return {
    "Content-Type": "application/json",
    ...(await clerkAuthHeaders()),
  };
}

export type CloudStackInfo = {
  mode: string;
  services: {
    feeds: { backend: string; turso: boolean; supabase_writes: boolean };
    cache: { upstash: boolean };
    agents: { cloud_vault: boolean; supabase_writes: boolean };
    auth: { supabase: boolean };
  };
  recommendations: string[];
  vault_gist_configured: boolean;
};

export async function fetchCloudStack(): Promise<CloudStackInfo | null> {
  const cfg = getRuntimeConfig();
  try {
    const res = await fetch(`${cfg.supabaseUrl}/functions/v1/cloud-config`, {
      headers: await authHeaders(),
    });
    if (!res.ok) return null;
    return await res.json();
  } catch {
    return null;
  }
}

export async function cloudSaveArtifact<T>(opts: {
  agent: AgentNamespace;
  kind: string;
  title: string;
  data: T;
  id?: string;
}): Promise<{ id: string; gistId?: string } | null> {
  const cfg = getRuntimeConfig();
  try {
    const res = await fetch(`${cfg.supabaseUrl}/functions/v1/agent-vault`, {
      method: "POST",
      headers: await authHeaders(),
      body: JSON.stringify(opts),
    });
    const payload = await res.json().catch(() => ({}));
    if (!res.ok) return null;
    return { id: payload.id, gistId: payload.gistId };
  } catch {
    return null;
  }
}

export async function cloudListArtifacts<T>(agent: AgentNamespace): Promise<T[]> {
  const cfg = getRuntimeConfig();
  try {
    const res = await fetch(
      `${cfg.supabaseUrl}/functions/v1/agent-vault?agent=${encodeURIComponent(agent)}`,
      { headers: await authHeaders() },
    );
    if (!res.ok) return [];
    const payload = await res.json();
    return (payload.items ?? []).map((a: { data: T }) => a.data);
  } catch {
    return [];
  }
}

export function cloudVaultPreferred(): boolean {
  return import.meta.env.VITE_CLOUD_VAULT !== "false";
}
